(()=>{'use strict';
const D=window.ONESIMO_DATA,C=window.OnesimoCore,KEY='hoja-dnd:'+C.ID+':v1';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v===null?'—':new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}).format(v),sign=v=>(v>=0?'+':'')+v;
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
let state=C.initial(D),protectedSave=false,storageOkay=true,rawBad='',currentTab='ficha',dialogBusy=false,toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw)state=C.validate(JSON.parse(raw));localStorage.setItem(KEY+':probe','1');localStorage.removeItem(KEY+':probe');}catch{storageOkay=false;try{rawBad=localStorage.getItem(KEY)||'';}catch{}protectedSave=!!rawBad;warnStorage(protectedSave?'El guardado existente no se puede validar y se conserva intacto. No se sobrescribirá. Descarga el original desde Bitácora antes de restablecer.':'Este navegador no permite guardar aquí. La hoja funciona en memoria: exporta un JSON antes de cerrar.');}
function warnStorage(t){$('#storage-warning').hidden=false;$('#storage-warning').textContent=t;}
function toast(t){const n=$('#toast');n.textContent=t;n.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('visible'),4500);}
function save(){state.updatedAt=new Date().toISOString();if(!protectedSave){try{localStorage.setItem(KEY,JSON.stringify(state));storageOkay=true;}catch{storageOkay=false;warnStorage('No se pudo guardar. Los datos siguen en memoria; exporta un respaldo JSON antes de cerrar.');}}$('#save-status').textContent=protectedSave?'Guardado protegido · revisar Bitácora':storageOkay?'Guardado local · '+new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}):'Sin guardado · exporta un JSON';updateSummary();}
async function confirmChange(title,text){if(dialogBusy)return false;dialogBusy=true;const d=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;d.returnValue='cancel';d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>{dialogBusy=false;resolve(d.returnValue==='ok');},{once:true}));}
function card(title,body,span=6){return `<article class="card span${span}"><h2>${title}</h2>${body}</article>`;}
function banner(title,text,art='onesimo-fogini.png'){return `<div class="section-media"><div class="section-media__copy"><div class="eyebrow">${title}</div><p>${text}</p></div><img src="assets/imagen/${art}" alt="Referencia visual de Onésimo y Fogini" width="116" height="116" loading="lazy"></div>`;}
function input(id,label,type='text',value='',attrs=''){return `<label>${label}<input id="${id}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;}
function opt(value,label,selected){return `<option value="${esc(value)}"${String(value)===String(selected)?' selected':''}>${esc(label)}</option>`;}
function select(id,label,options,selected){return `<label>${label}<select id="${id}">${options.map(x=>opt(x[0],x[1],selected)).join('')}</select></label>`;}
function check(id,label,checked=false){return `<label class="checkline"><input id="${id}" type="checkbox"${checked?' checked':''}>${label}</label>`;}
function kv(label,value){return `<div class="kv"><span>${label}</span><strong>${value}</strong></div>`;}
function fogStatus(){return state.fog.status==='active'?'Invocado':state.fog.status==='absent'?'Ausente':'Por registrar';}
function concentrationName(){return state.concentration==='mark'?'Marca del cazador':state.concentration==='pass'?'Pasar sin dejar rastro':'Ninguna registrada';}
function stat(label,value,sub=''){return `<div class="statbox"><b>${value}</b><span>${label}</span>${sub?`<div class="substat">${sub}</div>`:''}</div>`;}
function resourcePanel(){return `<div class="resource-head"><span>PG de Onésimo</span><b>${fmt(state.hp)} / ${C.maxHP(state)}</b></div><div class="meter"><div style="width:${state.hp===null?0:Math.min(100,state.hp/Math.max(1,C.maxHP(state))*100)}%"></div></div><div class="mutedline">${fmt(state.temp)} temporales · ${fmt(state.hd)} / 5d10 disponibles</div>${kv('Espacios de nivel 1',fmt(state.slots1)+' / 4')}${kv('Espacios de nivel 2',fmt(state.slots2)+' / 2')}${kv('Flechas disponibles',fmt(state.arrows))}${kv('Concentración',esc(concentrationName()))}${kv('Invocaciones de Fogini',fmt(state.fog.uses)+' / 3')}${kv('Fogini',fogStatus()+' · '+fmt(state.fog.hp)+' / 19 PG')}${kv('Resistencia al fuego de Onésimo',state.fog.bondActive?'Vínculo registrado activo':'No registrada activa')}<div class="buttonrow rowgap"><button class="btn" data-go="mesa">Administrar en sesión →</button><button class="btn" data-go="simulador">Construir un turno →</button></div>`;}
function spellTable(){return `<div class="tablewrap"><table class="spelltable"><thead><tr><th>Conjuro</th><th>Tiempo / nivel</th><th>Alcance</th><th>Uso y límite</th></tr></thead><tbody>${D.spells.map(s=>`<tr><td><div class="spellname"><span class="spell-symbol ${s.id}">${s.symbol}</span><b>${s.name}</b></div></td><td>${s.time}<br><small>Nivel ${s.level} · ${s.concentration?'Concentración':'Sin concentración'}</small></td><td>${s.range}</td><td>${s.id==='mark'?'+1d6 en cada impacto propio de arma; compite con Fogini por acción adicional.':s.id==='cure'?'1d8+3 o 2d8+3 de curación, según espacio; toque.':s.id==='animals'?'Comunicación con bestias durante 10 minutos.':'+10 a Sigilo; sustituye Marca si la mantenías.'}</td></tr>`).join('')}</tbody></table></div>`;}
function renderFicha(){
$('#ficha').innerHTML=banner('Onésimo · El arquero y la llama','Identidad, armas, magia y estado actual de los dos compañeros.')+`<div class="barstats">${stat('CA',15,'Cuero 11 + DES 4')}${stat('PG actuales / máximo',fmt(state.hp)+' / '+C.maxHP(state))}${stat('Iniciativa','+4')}${stat('Velocidad','35','pies · base')}${stat('Competencia','+3')}${stat('CD de conjuro',14,'Ataque +6')}</div><div class="grid">${card('Identidad y características',`<div class="abilities">${D.abilities.map(a=>`<div class="ability"><small>${a[1]}</small><strong>${a[2]}</strong><em>${sign(Math.floor((a[2]-10)/2))}</em></div>`).join('')}</div><hr class="separator"><div class="grid"><div class="span6">${kv('Especie','Elfo de los bosques')}${kv('Clase / nivel','Explorador 5')}${kv('Subclase','Elementalista · comunidad')}${kv('Campaña',esc(state.campaign)||'Por registrar')}</div><div class="span6">${kv('Estilo','Arquería')}${kv('Compañero','Fogini · elemental de fuego')}${kv('Trasfondo','No documentado')}${kv('Alineamiento','No documentado')}</div></div><p class="reading-note">Puntuaciones transcritas; modificadores derivados. No se completan origen, familia o elecciones de terreno/enemigo sin confirmación.</p>`,8)}${card('Salvaciones y percepción',`<div class="triples">${stat('Percepción pasiva',16)}${stat('Dados de golpe','5d10')}${stat('Ataque de conjuro','+6')}${stat('CD de conjuro',14)}${stat('DES','+4')}${stat('SAB','+3')}</div><hr class="separator">${D.saves.map(x=>kv(x[0],sign(x[1]))).join('')}<p class="mutedline">Competencia de explorador en Fuerza y Destreza. Sabiduría gobierna sus conjuros, según la hoja 02.</p>`,4)}${card('Armamento y ataques',`<div class="tablewrap"><table><thead><tr><th>Arma</th><th>Impacto</th><th>Daño por impacto</th><th>Alcance</th></tr></thead><tbody><tr><td><span class="item-ident"><img src="assets/icono/inventario/bow.svg" alt=""><span>Arco largo</span></span></td><td>+9</td><td>1d8 + 4 perforante</td><td>150 / 600 pies</td></tr><tr><td><span class="item-ident"><img src="assets/icono/inventario/sword.svg" alt=""><span>Espada corta</span></span></td><td>+7</td><td>1d6 + 4 perforante</td><td>5 pies</td></tr></tbody></table></div><div class="notice rowgap"><b>Ataque Extra:</b> dos ataques al tomar Atacar en tu turno. <b>Marca:</b> +1d6 por cada impacto de Onésimo contra el objetivo marcado. Fogini no recibe ese dado.</div><p class="mutedline">Arco: dos manos, munición. Espada: ligera y sutil. La cantidad de flechas queda por registrar; la imagen no confirma un número.</p>`,6)}${card('Recursos actuales',resourcePanel(),6)}${card('Magia de explorador',spellTable()+`<p class="mutedline">Cuatro conjuros conocidos; sin trucos registrados. Espacios máximos: 4 de nivel 1 y 2 de nivel 2. Recuperación con descanso largo.</p>`,8)}${card('Fogini',`<div class="fogart"><img src="assets/imagen/fogini-ficha.png" alt="Fogini, salamandra roja con cresta de fuego, en la imagen aportada"></div><span class="chip fire">Reglas caseras de la mesa</span>${kv('CA / PG de referencia','12 / 19')}${kv('Movimiento / trepar','30 / 30 pies')}${kv('Iniciativa','+2 registrada')}${kv('Mordida ígnea','+4 · 5 pies')}<p>1d8 + 2 perforante + 1d4 fuego.</p><p class="source-note">Inmune al fuego. Tres invocaciones por descanso largo, duración una hora. Invocar y ordenar atacar usan la acción adicional de Onésimo; son opciones distintas.</p>`,4)}${card('Habilidades importantes',`<div class="grid"><div class="span6">${D.skills.map(x=>kv(x[0]+' <small>('+x[1]+')</small>',sign(x[2]))).join('')}</div><div class="span6"><h3>Lo que puedes consultar</h3><p>Percepción para detectar, Supervivencia para rastrear, Sigilo para esconderte, Trato con animales para influir en bestias y Perspicacia para interpretar intenciones.</p><p class="source-note">La hoja solo enumera estas seis habilidades. Las demás competencias no se deducen ni se asignan por ausencia. El terreno predilecto y enemigo concreto están pendientes.</p><button class="btn" data-go="reglas">Leer reglas y rasgos →</button></div></div>`,12)}</div>`;
}
function renderLore(){
$('#lore').innerHTML=banner('Onésimo · Su camino','Solo historia y vínculos documentados. Las notas del jugador permiten desarrollar lo que aún no se conoce.')+`<div class="grid">${card('Dos naturalezas. Un mismo camino.',`<p class="lorequote">«Mientras la naturaleza arde, yo sigo caminando. En cada huella queda una historia, y en cada brasa, un hogar». — Onésimo</p><p>Onésimo es un elfo de los bosques y explorador. Combate con arco largo y espada corta y está vinculado a Fogini, un compañero elemental de fuego. Los documentos sitúan a ambos en Deathsleep.</p><p>No se proporciona una biografía, origen concreto, edad, familia, alineamiento, trasfondo, ideales o defectos. No se convierten el paisaje de ruinas o los textos temáticos de las imágenes en acontecimientos confirmados de su pasado.</p><h3>Un vínculo documentado</h3><p>«Fuego que camina a mi lado. Más que una bestia, eres mi hogar en la batalla». — Onésimo</p><p>La hoja presenta a Onésimo y Fogini como compañeros inseparables, que exploran, protegen y se enfrentan juntos a las amenazas. Ese vínculo es tanto narrativo como una regla de campaña: la resistencia al fuego depende de que el vínculo elemental esté activo.</p>`,8)}${card('Apariencia en las referencias',`<img class="miniart" src="assets/imagen/onesimo-fogini.png" alt="Ilustración completa aportada de Onésimo y Fogini"><p class="rowgap">Onésimo aparece con cabello castaño largo, orejas élficas, capa verde y equipo de cuero, con arco y carcaj. Fogini aparece como una salamandra roja grande, con cresta de fuego.</p><p class="source-note">Descripción visual observada; el carcaj no aporta una cantidad de flechas. La apariencia no añade objetos mágicos ni estadísticas.</p>`,4)}${card('Fogini · temperamento',`<p>Leal, protector, feroz, atento, territorial ante las amenazas y dócil con su guardián. La imagen lo describe con temperamento ardiente, pero obediente.</p><h3>Rutina de compañero</h3><p>Avanza junto a Onésimo, protege su flanco, ataca cuando recibe la orden e intimida con su presencia ígnea. «Proteger» o «intimidar» no se convierten automáticamente en una acción especial, bonificador o daño de aura no documentado.</p><p class="tagline">«Donde uno deja un camino, el otro deja su huella de fuego».</p>`,6)}${card('Lo que sucede después',`<label class="field">Notas narrativas del jugador · guardado automático<textarea id="lore-notes" data-bind="lore" rows="11" maxlength="100000" placeholder="Hechos vividos, nuevas relaciones, decisiones, objetivos y evolución de Onésimo…">${esc(state.lore)}</textarea></label><p class="source-note">El lore editable y la bitácora se incluyen en el JSON. Anotar una propuesta de regla no la convierte en una mecánica activa.</p>`,6)}</div>`;
}
function spellDetail(s){return `<details class="spell-details" data-search="${esc((s.name+' '+s.en+' '+s.text+' '+s.limits).toLowerCase())}"><summary><span class="spellname"><span class="spell-symbol ${s.id}">${s.symbol}</span>${s.name}</span><span class="tag">Nv. ${s.level}${s.concentration?' · C':''}</span></summary><div class="spellmeta"><span class="pill">${s.time}</span><span class="pill">${s.range}</span></div><p>${esc(s.text)}</p><p class="notice">${esc(s.limits)}</p><p class="mutedline"><b>Componentes:</b> ${esc(s.components)}<br><b>Duración:</b> ${esc(s.duration)}<br><b>Coste:</b> un espacio de nivel ${s.level===2?'2':'1 o 2'}. <b>Recuperación:</b> descanso largo.</p><p class="source-note">Conocido según hoja 02; funcionamiento de 2014. C indica concentración. Fuentes en Oficialidad.</p></details>`;}
function renderReglas(){
$('#reglas').innerHTML=banner('Onésimo · Reglas de consulta','Acciones, conjuros y límites explicados para jugar. Los rasgos raciales completados desde reglas se distinguen de las elecciones pendientes.')+`<div class="rule-actions"><label class="field">Buscar regla o capacidad<input id="rules-search" type="search" placeholder="Marca, Fogini, descanso, concentración…"></label><button class="btn" id="expand-rules">Expandir resultados</button></div><div class="grid">${card('Tus cuatro conjuros',D.spells.map(spellDetail).join('')+`<div class="notice">Marca y Pasar sin dejar rastro exigen concentración. No se suman. Hablar con los animales y Curar heridas no la necesitan.</div>`,6)}${card('Manual del explorador',D.rules.map(r=>`<details data-search="${esc((r[0]+' '+r[1]).toLowerCase())}"><summary>${esc(r[0])}</summary><p class="rowgap">${esc(r[1])}</p></details>`).join(''),6)}</div><p id="rules-empty" class="empty" hidden>No hay resultados para esa búsqueda.</p><p class="source-note">Tiempo y geometría del mundo de juego se resuelven con el DM. Las duraciones no avanzan con el reloj real del navegador.</p>`;
}
function simForm(){return `<form id="sim-form"><div class="formgrid">${input('sim-distance','Distancia al objetivo de Onésimo (pies)','number',30,'min="0" max="10000" required')}${input('sim-move','Movimiento previsto (pies)','number',0,'min="0" max="10000" required')}${select('sim-direction','Dirección',[['toward','Acercarse'],['away','Alejarse'],['lateral','Lateral · misma distancia']],'toward')}${select('sim-action','Acción principal',Object.entries(C.ACTIONS),'bow')}${select('sim-attackCount','Ataques al usar Atacar',[[2,'2 · Ataque Extra'],[1,'1 · Un ataque']],'2')}${select('sim-bonus','Acción adicional',Object.entries(C.BONUSES),'none')}${select('sim-slotLevel','Espacio para acción mágica / Sentidos',[[1,'Nivel 1'],[2,'Nivel 2']],1)}${select('sim-markLevel','Espacio para lanzar Marca',[[1,'Nivel 1'],[2,'Nivel 2']],1)}${input('sim-target','Objetivo de Marca','text',state.markTarget,'maxlength="200"')}${select('sim-reaction','Reacción prevista o ejecutada',Object.entries(C.REACTIONS),'none')}</div>${check('sim-markOnTarget','Los ataques elegidos se dirigen a mi objetivo ya marcado')}${check('sim-previousZero','El objetivo anterior de Marca cayó a 0 PG en un turno anterior')}<details><summary>Visión, manos y condiciones de Onésimo</summary>${check('sim-weaponReady','Arma lista: manos y munición accesibles',true)}${check('sim-visible','Veo al objetivo',true)}${check('sim-pathClear','No hay cobertura total y existe trayectoria válida',true)}${check('sim-canSpeak','Puedo hablar (componente V)',true)}${check('sim-components','Tengo mano libre y componentes necesarios para el conjuro',false)}${check('sim-hostileNear','Hay un hostil no incapacitado que me ve a 5 pies')}${check('sim-difficult','Terreno difícil en combate')}${check('sim-stand','Levantarme si estoy tumbado')}${check('sim-charmSafe','Confirmado: mi objetivo no es quien me hechizó')}${check('sim-fearSafe','Confirmado: no me acerco a la fuente del miedo')}${check('sim-hidePossible','DM: puedo intentar esconderme aquí')}${check('sim-helpPossible','DM: mi ayuda al aliado es viable',true)}${check('sim-favoredTerrain','Estoy en mi terreno predilecto confirmado en Mesa')}</details><details id="fog-command-controls"><summary>Orden de ataque a Fogini</summary><p class="mutedline">Solo se añade mordida si eliges la acción adicional Ordenar. Su momento de actuación se confirma con el DM.</p><div class="formgrid">${input('sim-fogDistance','Distancia de Fogini al objetivo (pies)','number',10,'min="0" max="10000"')}${input('sim-fogMove','Movimiento de Fogini hacia el objetivo (pies)','number',5,'min="0" max="10000"')}</div>${check('sim-fogDifficult','Terreno difícil para Fogini')}${check('sim-fogPathClear','Trayectoria y acceso al objetivo válidos para Fogini',true)}${check('sim-fogOrderPossible','Fogini recibe la orden y puede actuar en el momento acordado con el DM')}</details><details id="summon-controls"><summary>Invocar a Fogini · acción adicional confirmada</summary><p class="notice">Tres usos por descanso largo y una hora de duración están documentados. Los PG al aparecer o reaparecer no están especificados: introduce el valor acordado; no se restauran automáticamente.</p>${input('sim-summonHP','PG al aparecer, confirmados con el DM (máximo 19)','number','','min="1" max="19" step="1"')}${check('sim-summonResolved','El DM resolvió los detalles de aparición pendientes')}${check('sim-summonBond','El vínculo elemental estará activo al aparecer')}</details><details id="healing-controls"><summary>Curar heridas y receptor</summary>${check('sim-healSelf','La curación es para Onésimo',true)}${check('sim-healTargetValid','El receptor no es no muerto ni constructo',true)}<p class="source-note">El simulador no aplica una media como curación real. Tras consumir el espacio, usa Mesa con el resultado real de los dados si Onésimo fue el receptor.</p></details><details id="reaction-controls"><summary>Reacción: condiciones del desencadenante</summary>${input('sim-reactionDistance','Distancia al salir de mi alcance (pies)','number',5,'min="0" max="10000"')}${check('sim-reactionTrigger','Vi al enemigo salir voluntariamente de mi alcance sin Retirarse')}${check('sim-reactionVisible','Puedo ver a la criatura de la oportunidad',true)}${check('sim-reactionSwordReady','La espada corta está en mi mano')}${check('sim-reactionMarked','Esa criatura es mi objetivo de Marca aún activa')}${check('sim-switchHandsConfirmed','DM: el cambio entre arco y espada pudo hacerse antes de la reacción')}</details><label class="field rowgap">Contexto / acción preparada / condiciones relevantes<textarea id="sim-context" maxlength="2000" rows="3" placeholder="Cobertura, qué preparo, cuándo puede actuar Fogini…"></textarea></label></form>`;}
function renderSimulador(){
$('#simulador').innerHTML=banner('Onésimo · Simulador de turnos','La marca, el arco y la orden a Fogini: calcula una combinación antes de consumir sus recursos.')+`<div class="quick"><button class="btn" data-preset="mark"><strong>La primera huella</strong><small>Marca + dos flechas</small></button><button class="btn" data-preset="pair"><strong>Flecha y colmillo</strong><small>Arco + orden a Fogini</small></button><button class="btn" data-preset="summon"><strong>Fuego a mi lado</strong><small>Arco + invocar compañero</small></button><button class="btn" data-preset="stealth"><strong>Huellas que se apagan</strong><small>Pasar sin dejar rastro</small></button><button class="btn" data-preset="heal"><strong>Proteger al guardián</strong><small>Curar heridas + orden a Fogini</small></button></div><div class="simlayout"><article class="card"><h2>Construir un turno</h2>${simForm()}</article><article class="card simside"><h2>Resultado y restricciones</h2><span id="sim-badge" class="chip"></span><div id="sim-result" class="result"></div><button id="apply-turn" class="btn primary rowgap">Aplicar turno y consumo</button><p class="source-note">Requiere confirmación. El daño es teórico y los dados se resuelven en mesa. La invocación no incluye una orden de ataque adicional. Una reserva de reacción no se consume.</p></article></div>`;updateSim();
}
function readSim(){const value=k=>$('#sim-'+k).value,n=k=>value(k).trim()===''?NaN:Number(value(k)),b=k=>$('#sim-'+k).checked;return {action:value('action'),bonus:value('bonus'),reaction:value('reaction'),direction:value('direction'),target:value('target'),context:value('context'),...Object.fromEntries(['distance','move','attackCount','slotLevel','markLevel','fogDistance','fogMove','summonHP','reactionDistance'].map(k=>[k,n(k)])),...Object.fromEntries(['markOnTarget','previousZero','weaponReady','visible','pathClear','canSpeak','components','hostileNear','difficult','stand','charmSafe','fearSafe','hidePossible','helpPossible','favoredTerrain','fogDifficult','fogPathClear','fogOrderPossible','summonResolved','summonBond','healSelf','healTargetValid','reactionTrigger','reactionVisible','reactionSwordReady','reactionMarked','switchHandsConfirmed'].map(k=>[k,b(k)]))};}
function updateSim(){if(!$('#sim-form'))return;const i=readSim(),r=C.simulate(state,i);$('#fog-command-controls').hidden=i.bonus!=='command';$('#summon-controls').hidden=i.bonus!=='summon';$('#healing-controls').hidden=i.action!=='cure';$('#reaction-controls').hidden=!['opportunity','reserve'].includes(i.reaction);$('#sim-badge').textContent=r.valid?'Combinación válida':'Revisar antes de aplicar';$('#sim-badge').className='chip '+(r.valid?'':'fire');$('#apply-turn').disabled=!r.valid;$('#sim-result').innerHTML=`<small>PROMEDIO TEÓRICO CONDICIONADO · SIN REACCIÓN</small><div class="stat">${fmt(r.totalAverage)}</div><p class="mutedline">Onésimo ${fmt(r.ownAverage)} + Fogini ${fmt(r.fogAverage)}.</p>${kv('Acción',esc(r.action))}${kv('Acción adicional',esc(r.bonus))}${kv('Ataques de Onésimo',r.attacks)}${kv('Daño propio',esc(r.formula))}${kv('Daño de Fogini',esc(r.fogFormula))}${kv('Movimiento',fmt(r.moveCost)+' / '+fmt(r.moveBudget)+' pies')}${kv('Distancia tras moverse',fmt(r.distance)+' pies')}${kv('Espacios a consumir','Nv. 1: '+r.cost1+' · Nv. 2: '+r.cost2)}${kv('Flechas / invocaciones',r.arrows+' / '+r.uses)}${kv('Reacción',esc(r.reaction))}${r.healingAverage!==null?kv('Curación teórica media',fmt(r.healingAverage)+' · no aplicada'):''}<ul>${r.details.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${r.errors.length?`<div class="notice bad"><b>No se descontarán recursos</b>${r.errors.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}<details open><summary>Advertencias y supuestos</summary>${r.warnings.map(t=>`<p class="small">${esc(t)}</p>`).join('')}</details>`;}
async function applyTurn(){const i=readSim(),r=C.simulate(state,i);if(!r.valid)return toast(r.errors[0]);const rev=state.updatedAt;const text=`${r.action}\n${r.bonus}\nEspacios: ${r.cost1} de nivel 1 y ${r.cost2} de nivel 2.\nFlechas: ${r.arrows}. Invocaciones: ${r.uses}.\n${i.bonus==='summon'?'Fogini aparecerá con '+i.summonHP+' PG, valor que has confirmado con el DM.\n':''}${r.warnings.some(t=>t.includes('concentración anterior'))?'El nuevo lanzamiento termina la concentración anterior.\n':''}Confirma los supuestos de la combinación. No se aplicará daño ni curación media como resultado real.`;if(!await confirmChange('Aplicar turno',text))return;if(rev!==state.updatedAt)return toast('El estado cambió durante la confirmación. Revisa el turno de nuevo.');try{state=C.apply(state,i);addLog('Combate','Turno aplicado · '+r.action,`${r.action}. ${r.bonus}. Espacios gastados: nivel 1 ${r.cost1}, nivel 2 ${r.cost2}; flechas ${r.arrows}; invocaciones ${r.uses}. ${i.context||''}`,'Daño y curación reales pendientes de resolución en mesa.');save();refresh();toast('Turno aplicado. Resuelve las tiradas en mesa.');}catch(e){toast(e.message);}}
function renderInventory(){return state.inventory.length?state.inventory.map(i=>`<div class="itemrow" data-item="${esc(i.id)}"><img src="assets/icono/inventario/${i.icon}.svg" alt=""><div><label>Objeto<input data-item-field="name" maxlength="200" value="${esc(i.name)}"></label><label>Descripción<textarea data-item-field="notes" rows="2" maxlength="5000">${esc(i.notes)}</textarea></label><label>Procedencia<select data-item-field="kind">${['Poseído · hoja','Poseído · añadido','Personalizado','Referencia · no poseído'].map(k=>opt(k,k,i.kind)).join('')}</select></label></div><div><label>Cantidad<input data-item-field="qty" type="number" min="0" max="99999" step="1" value="${i.qty}"></label><button class="btn danger" data-delete-item="${esc(i.id)}">Quitar</button></div></div>`).join(''):'<p class="empty">No hay objetos registrados.</p>';}
function renderMesa(){
$('#mesa').innerHTML=banner('Onésimo · Mesa y recursos','Administra el estado real de la sesión. Los controles manuales registran hechos; lanzar y consumir se hace desde el simulador.')+`${state.hp===null?'<div class="notice">Los recursos actuales y la munición no están confirmados. Regístralos antes de aplicar un turno. Confirmar recursos completos no inventa flechas ni activa a Fogini.</div>':''}<div class="grid">${card('Estado de Onésimo',`<form id="resource-form"><div class="formgrid">${input('res-hp','PG actuales','number',state.hp,'min="0" max="1000" required')}${input('res-hpMax','PG máximos base · hoja 44','number',state.hpMax,'min="1" max="1000" required')}${input('res-temp','PG temporales','number',state.temp,'min="0" max="1000" required')}${input('res-hd','Dados de golpe restantes · 5d10 máximo','number',state.hd,'min="0" max="5" required')}${input('res-slots1','Espacios restantes · nivel 1 (máx. 4)','number',state.slots1,'min="0" max="4" required')}${input('res-slots2','Espacios restantes · nivel 2 (máx. 2)','number',state.slots2,'min="0" max="2" required')}${input('res-arrows','Flechas disponibles · cantidad no documentada','number',state.arrows,'min="0" max="99999" placeholder="Pendiente"')}${input('res-round','Ronda / turno de referencia','number',state.round,'min="1" max="999999" required')}</div>${check('res-reaction','Reacción disponible',state.reactionAvailable)}<div class="buttonrow"><button class="btn primary" type="submit">Registrar estado</button><button type="button" class="btn" id="full-resources">Confirmar recursos completos</button></div></form><p class="source-note">Las flechas se gestionan aquí, no como un segundo contador de inventario. Recupera manualmente las que se hayan recuperado en la ficción. Un máximo de PG editado es un registro del jugador, no un cambio automático de nivel.</p><hr class="separator"><div class="buttonrow"><button class="btn primary" id="next-turn">Comenzar siguiente turno</button></div><p class="mutedline">Turno ${state.round}: ${state.turnApplied?'ya aplicado':'disponible'}. La reacción se recupera al comienzo de tu siguiente turno, no al aplicar este.</p>`,8)}${card('Pulso de la sesión',resourcePanel(),4)}${card('Daño y curación',`<div class="formgrid">${input('damage-amount','Daño antes de resistencia','number','','min="1" max="100000" step="1"')}${select('damage-target','Receptor del daño',[['onesimo','Onésimo'],['fog','Fogini']],'onesimo')}${select('damage-type','Tipo de daño',[['other','Otro daño'],['fire','Fuego']],'other')}${input('heal-amount','Curación real recibida por Onésimo','number','','min="1" max="100000" step="1"')}</div>${check('damage-critical','El daño recibido a 0 PG fue un crítico')}<div class="buttonrow"><button class="btn" id="apply-damage">Aplicar daño</button><button class="btn" id="apply-heal">Aplicar curación</button></div><p id="damage-result" class="mutedline rowgap" role="status"></p><p class="source-note">Fuego: Fogini es inmune; Onésimo resiste solo con vínculo registrado activo. Petrificado da resistencia a todo daño, sin acumular varias resistencias. Otras reducciones o vulnerabilidades se resuelven con el DM antes de registrar.</p><hr class="separator"><h3>Concentración</h3>${state.pendingConcentrationDC!==null?`<div class="notice bad">Prueba pendiente: CON +2 contra CD ${state.pendingConcentrationDC}. Se conserva al recargar.</div>`:''}<div class="inline-input">${input('con-roll','Resultado natural del d20','number','','min="1" max="20" step="1"')}${input('con-dc','CD de concentración','number',state.pendingConcentrationDC||10,'min="10" max="50000" step="1"')}<button class="btn" id="resolve-concentration">Resolver +2</button></div><p class="source-note">Tira en mesa; con agotamiento 3 o superior, recuerda desventaja en salvaciones. Un 1 o 20 no produce fallo/éxito automático en esta salvación.</p>`,8)}${card('Efectos y posición',`<div class="formgrid">${select('concentration','Concentración ya activa',[['none','Ninguna'],['mark','Marca del cazador'],['pass','Pasar sin dejar rastro']],state.concentration)}${input('mark-target','Objetivo de Marca','text',state.markTarget,'maxlength="200"')}</div><button class="btn rowgap" id="record-concentration">Registrar efecto ya lanzado</button><p class="source-note">No consume un espacio porque registra un lanzamiento previo. Para lanzar ahora usa el simulador; otra concentración termina la anterior.</p><label class="field">Posición de Onésimo<input data-bind="position" value="${esc(state.position)}" maxlength="1000" placeholder="Cobertura, distancias, altura…"></label><label class="field rowgap">Enemigo predilecto confirmado<input data-bind="favoredEnemy" value="${esc(state.favoredEnemy)}" maxlength="1000" placeholder="Elección pendiente"></label><label class="field rowgap">Terreno predilecto confirmado<input data-bind="favoredTerrain" value="${esc(state.favoredTerrain)}" maxlength="1000" placeholder="Bosque era una sugerencia, no una elección"></label>`,4)}${card('Fogini · estado y vínculo',`<div class="fog-status"><span class="chip fire">${fogStatus()}</span> <b>${fmt(state.fog.hp)} / 19 PG</b> · Usos ${fmt(state.fog.uses)} / 3</div><form id="fog-form" class="rowgap"><div class="formgrid">${select('fog-status','Estado registrado',[['unknown','Por registrar'],['absent','Ausente'],['active','Invocado'] ],state.fog.status)}${input('fog-hp','PG actuales de Fogini','number',state.fog.hp,'min="0" max="19" placeholder="Pendiente"')}${input('fog-uses','Invocaciones restantes','number',state.fog.uses,'min="0" max="3" placeholder="Pendiente"')}${input('fog-minutes','Minutos restantes (manual, máx. 60)','number',state.fog.remainingMinutes,'min="0" max="60" placeholder="Por registrar"')}</div>${check('fog-bond','Vínculo elemental activo: Onésimo resiste fuego',state.fog.bondActive)}<div class="buttonrow"><button class="btn" type="submit">Registrar estado ya resuelto</button><button class="btn" type="button" id="end-fog">Finalizar invocación y vínculo</button></div></form><p class="source-note">Este formulario no invoca ni consume un uso. Para invocar ahora, elige Invocar a Fogini en el simulador: acción adicional y un uso. Sus PG de aparición se introducen según lo confirmado en mesa, porque no se especifican. El descanso largo recupera usos, no cura al compañero automáticamente. El vínculo se registra por separado: su persistencia al desaparecer Fogini no está especificada. Finalizar no devuelve usos.</p><label class="field">Posición de Fogini<input data-fog-bind="position" value="${esc(state.fog.position)}" maxlength="1000" placeholder="Flanco, altura o trepando, distancia…"></label><details><summary>Condiciones de Fogini</summary><div class="checks">${C.CONDITIONS.map(c=>`<label><input type="checkbox" data-fog-condition="${c}"${state.fog.conditions.includes(c)?' checked':''}>${c}</label>`).join('')}</div></details>`,8)}${card('Descansos y recuperación',`<div class="buttonrow"><button class="btn" id="short-rest">Descanso corto</button><button class="btn" id="long-rest">Descanso largo</button></div>${check('rest-food','Comida y bebida suficientes para reducir un nivel de agotamiento',true)}<div class="notice">Corto: no recupera espacios ni invocaciones. Largo: PG, espacios 4/2, hasta dos dados de golpe y tres usos de Fogini. No restaura sus PG ni decide automáticamente si el vínculo continúa.</div><h3>Gastar dado de golpe al descansar</h3><div class="inline-input">${input('hd-roll','Resultado real del d10','number','','min="1" max="10" step="1"')}<button class="btn" id="spend-hd">Gastar 1d10 · curar +2</button></div><p class="source-note">Último descanso largo registrado: ${state.lastLongRest?esc(new Date(state.lastLongRest).toLocaleString('es-MX')):'ninguno'}. El requisito de 24 horas corresponde a la ficción, no al reloj del ordenador.</p>`,4)}${card('Condiciones de Onésimo',`<div class="checks">${C.CONDITIONS.map(c=>`<label><input type="checkbox" data-condition="${c}"${state.conditions.includes(c)?' checked':''}>${c}</label>`).join('')}</div><div class="formgrid rowgap">${select('exhaustion','Agotamiento',[[0,'0 · Ninguno'],[1,'1 · Desventaja en pruebas'],[2,'2 · Velocidad a la mitad'],[3,'3 · Desventaja en ataques y salvaciones'],[4,'4 · Máximo PG a la mitad'],[5,'5 · Velocidad 0'],[6,'6 · Muerte']],state.exhaustion)}${input('death-success','Éxitos de salvación de muerte','number',state.deathSuccess,'min="0" max="3" step="1"')}${input('death-fail','Fallos de salvación de muerte','number',state.deathFail,'min="0" max="3" step="1"')}</div><div class="buttonrow rowgap"><button class="btn" id="record-death">Registrar salvaciones</button><button class="btn" id="death-20">20 natural: 1 PG</button></div><p class="source-note">A 0 PG el simulador considera a Onésimo inconsciente automáticamente. Las condiciones marcadas manualmente conservan su causa hasta que las retires. ${state.deathFail>=3?'Tres fallos: muerte registrada.':state.deathSuccess>=3?'Tres éxitos: estable a 0 PG.':''}</p>`,8)}${card('Notas rápidas de sesión',`<label class="field">Guardado automático<textarea data-bind="notes" rows="12" maxlength="50000" placeholder="Iniciativas, objetivos, duraciones, decisiones pendientes…">${esc(state.notes)}</textarea></label>`,4)}${card('Inventario',`<div id="inventory-list">${renderInventory()}</div><hr class="separator"><form id="item-form"><div class="formgrid">${input('item-name','Objeto','text','','maxlength="200" required')}${input('item-qty','Cantidad','number',1,'min="0" max="99999" step="1" required')}${select('item-kind','Procedencia',[['Poseído · añadido','Poseído · añadido'],['Personalizado','Personalizado · documenta aprobación'],['Referencia · no poseído','Referencia · no poseído']],'Poseído · añadido')}${select('item-icon','Icono de categoría',[['bag','Equipo'],['bow','Arco'],['sword','Espada'],['armor','Armadura'],['arrows','Munición']],'bag')}</div><label class="field rowgap">Descripción / origen / autorización<textarea id="item-notes" maxlength="5000" rows="2"></textarea></label><button class="btn rowgap" type="submit">Añadir objeto</button></form><p class="source-note">Solo hay arco largo, espada corta y cuero registrados como equipo. Monedas, herramientas, otros consumibles y cantidades adicionales quedan pendientes. Las flechas se cuentan en Estado de Onésimo. Cambiar el nombre exacto del arco o espada desvincula ese objeto del ataque configurado.</p>`,8)}${card('Biblioteca mínima de equipo',`<div class="item-gallery">${[['bow','Arco largo'],['sword','Espada corta'],['armor','Cuero'],['arrows','Flechas'],['bag','Equipo añadido']].map(x=>`<div class="item-tile"><img src="assets/icono/inventario/${x[0]}.svg" alt="Icono ilustrativo de ${x[1]}"><span>${x[1]}</span></div>`).join('')}</div><p class="source-note">SVG originales de categorías pertinentes. La galería no añade posesiones. Flechas y bolsa son referencias visuales; las cantidades y objetos reales se registran en sus controles.</p>`,4)}</div>`;
}
function renderLogs(q=''){const list=state.logs.filter(l=>[l.title,l.body,l.session,l.type,l.date,l.continuity].join(' ').toLowerCase().includes(q.toLowerCase()));return list.length?list.slice().reverse().map(l=>`<article class="entry"><time>${esc(l.date)}</time> <span class="tag">${esc(l.type)}</span> <small>${esc(l.session)}</small><h3 class="rowgap">${esc(l.title)}</h3><p>${esc(l.body)}</p>${l.continuity?`<p class="continuity"><b>Continuidad:</b> ${esc(l.continuity)}</p>`:''}<button class="btn danger small" data-delete-log="${esc(l.id)}">Eliminar entrada</button></article>`).join(''):`<div class="empty">${q?'No hay coincidencias.':'La bitácora está lista para la primera sesión.'}</div>`;}
function renderBitacora(){const draft=state.logDraft||{};
$('#bitacora').innerHTML=banner('Onésimo · Memoria y respaldos','Registra lo vivido, busca decisiones y conserva una copia portable de la sesión.')+`<div class="grid">${card('Nuevo registro',`<form id="log-form"><div class="formgrid">${input('log-date','Fecha','date',draft.date||today(),'required data-log-draft="date"')}${input('log-session','Sesión o capítulo','text',draft.session||'','maxlength="120" data-log-draft="session"')}${select('log-type','Tipo de acontecimiento',['Combate','Exploración','Relación','Descubrimiento','Recompensa','Decisión del DM','Otro'].map(v=>[v,v]),draft.type||'Exploración')}${input('log-title','Título','text',draft.title||'','maxlength="200" required data-log-draft="title"')}<label class="full">Contenido narrativo<textarea id="log-body" maxlength="30000" rows="4" required data-log-draft="body">${esc(draft.body||'')}</textarea></label><label class="full">Continuidad · consecuencias, relaciones o pistas<textarea id="log-continuity" maxlength="10000" rows="2" data-log-draft="continuity">${esc(draft.continuity||'')}</textarea></label></div><button type="submit" class="btn primary rowgap">Guardar registro</button></form><p class="source-note">El borrador también se guarda mientras escribes. Las entradas automáticas del simulador no afirman un daño real que todavía no se haya resuelto.</p>`,8)}${card('Respaldos de Onésimo',`<label class="field">Nombre de campaña<input data-bind="campaign" maxlength="160" value="${esc(state.campaign)}"></label><div class="buttonrow rowgap"><button class="btn primary" id="export-json">Exportar JSON completo</button><button class="btn" id="export-text">Exportar bitácora TXT</button><button class="btn" id="copy-state">Copiar estado para compartir</button></div><textarea id="copy-fallback" readonly hidden aria-label="Estado para copiar manualmente"></textarea><p class="source-note">El JSON conserva a Onésimo y Fogini, recursos, objetos, condiciones, notas, lore, borrador y registros. Guarda también la carpeta con las imágenes.</p><hr class="separator"><label class="field">Importar respaldo JSON<input id="import-file" type="file" accept=".json,application/json"></label><p class="source-note">Se valida identidad, versión y estructura antes de confirmar. Al reemplazar se descarga una copia del estado anterior.</p>`,4)}${card('Historial de sesiones',`<label class="field">Buscar registros<input id="log-search" type="search" placeholder="Fecha, capítulo, título, texto o continuidad…"></label><div id="log-history" class="rowgap">${renderLogs()}</div>`,8)}${card('Integridad y almacenamiento',`<p>Los cambios se guardan en este navegador. Otra carpeta, otro equipo o navegador pueden tener un estado distinto; usa JSON para trasladarlo.</p>${kv('Esquema','v'+C.VERSION)}${kv('Identificador',C.ID)}${kv('Registros',state.logs.length)}${kv('Último cambio',esc(new Date(state.updatedAt).toLocaleString('es-MX')))}${rawBad?'<button class="btn rowgap" id="export-original">Descargar guardado original intacto</button>':''}<button class="btn danger rowgap" id="reset-state">Restablecer datos de Onésimo</button><p class="source-note">Pide confirmación y descarga un respaldo antes de restablecer. Solo afecta a esta configuración de Onésimo; otros personajes no se modifican.</p>`,4)}</div>`;
}
function audit(rows){return `<div class="tablewrap"><table class="source-comparison"><thead><tr><th>Elemento</th><th>Regla / fuente</th><th>Configuración usada</th><th>Procedencia</th></tr></thead><tbody>${rows.map(row=>'<tr>'+row.map((v,j)=>`<td>${j===3?'<span class="origin-key '+(v==='Oficial'?'is-rule':v.includes('DM')?'is-dm':v==='Comunidad'?'is-home':'is-pending')+'">'+v+'</span>':v}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`;}
function renderOficialidad(){
$('#oficialidad').innerHTML=banner('Onésimo · Oficialidad y Homebrew','Clasificación documental de lo registrado, las reglas de 2014 y las adaptaciones de vuestra mesa.')+`<div class="origin-legend"><div class="origin-card"><div><strong>Oficial · 2014</strong><p>Existencia y funcionamiento respaldados por reglas oficiales de la edición.</p></div></div><div class="origin-card"><div><strong>Comunidad</strong><p>Elementalista está descrita como comunitaria. No se aportó autor, enlace ni texto completo.</p></div></div><div class="origin-card"><div><strong>Autorizado por DM</strong><p>Estadísticas y vínculo de Fogini, según hoja 02; invocación bonus confirmada por el usuario.</p></div></div><div class="origin-card"><div><strong>Pendiente</strong><p>Elecciones o detalles que no constan. No se convierten en capacidades adicionales.</p></div></div></div><div class="notice rowgap">Esta pestaña no modifica las estadísticas ni el simulador. El usuario indicó que no tiene fuentes de la subclase y que los detalles no especificados deben quedar pendientes. El archivo de referencia de Eco se usó para estructura y diseño, sin tomar de él contenido del personaje.</div><div class="grid rowgap">${card('A · Especie, clase, subclase y características',audit([
 ['Elfo de los bosques / Explorador 5','Opciones oficiales de 2014. Raza, velocidad y clase se identifican en las hojas.','Características 10/18/14/8/16/10, competencia +3, CA 15, iniciativa +4, velocidad 35.','Oficial'],
 ['PG registrados 44 / 5d10','No se separan inequívocamente PG máximos y actuales. Coincide con promedio de explorador con CON +2.','44 como máximo de referencia editable; actuales por registrar.','Hoja registrada'],
 ['Salvaciones / seis habilidades','Valores transcritos; FUE y DES son salvaciones competentes de explorador.','FUE +3, DES +7, CON +2, INT −1, SAB +3, CAR +0. Seis habilidades tal como figuran.','Hoja registrada'],
 ['Elementalista','Las imágenes la clasifican como subclase de la comunidad.','No se equipara a Cazador ni Señor de las Bestias oficiales. No se incorporan rasgos adicionales de una versión externa no identificada.','Comunidad'],
 ['Trasfondo, alineamiento y elecciones','Ausentes: no se asignan mediante inferencia.','Enemigo y terreno predilectos se pueden registrar cuando se confirmen. Bosque solo se presenta como sugerido.','Pendiente']
 ]),12)}${card('B · Armas, armadura y equipo',audit([
 ['Arco largo','1d8 perforante, dos manos, munición, pesado, 150/600 pies. Estilo Arquería +2 a ataques a distancia.','+9 al ataque, 1d8+4; hasta dos disparos al Atacar. No añade daño de fuego.','Oficial'],
 ['Espada corta','1d6 perforante, ligera y sutil.','+7 y 1d6+4; dos ataques al Atacar. Una sola espada registrada, sin segunda arma inventada.','Oficial'],
 ['Armadura de cuero','CA 11 + Destreza.','CA 15; no se añaden escudo ni objetos mágicos.','Oficial'],
 ['Flechas, monedas, herramientas y otros objetos','El arte muestra equipo, pero no establece cantidades ni un inventario completo.','Flechas inicialmente pendientes; equipo inicial solo arco, espada y cuero. Galería visual separada.','Pendiente']
 ]),12)}${card('C · Rasgos y poderes',audit([
 ['Ataque Extra, Arquería, Enemigo predilecto, Explorador nato, Sentidos primigenios','Rasgos de explorador disponibles a nivel 5 en 2014.','Sin daño adicional de Enemigo predilecto. Terreno difícil de combate no se anula por Explorador nato. Sentidos consume un espacio, no un recurso inventado.','Oficial'],
 ['Rasgos de elfo de los bosques','Consulta oficial: visión 60 pies, Percepción, linaje feérico, trance, armas, velocidad y Máscara de la espesura.','Se explican como derivados de la especie identificada, no como historia personal. No se inventan idiomas de enemigo predilecto.','Oficial'],
 ['Fogini','CA 12, PG 19, Grande, 30 pies y trepar 30; iniciativa +2; mordida +4, 1d8+2 perforante +1d4 fuego a 5 pies. Inmune al fuego.','Configuración explícita, sin escalado automático, aliento o daño de aura. La hoja 02 marca autorización del DM.','Casera · DM'],
 ['Invocación y orden','Tres invocaciones por descanso largo, una hora, desaparece a 0. Ordenar ataque consume acción adicional según hojas. Usuario confirmó invocar como acción adicional.','Invocar, ordenar atacar y Marca son opciones mutuamente excluyentes de acción adicional. Los PG al aparecer deben introducirse como valor confirmado; no se presuponen 19.','Casera · DM'],
 ['Vínculo elemental','Resistencia al fuego mientras esté activo según hoja 02.','Seguimiento manual del vínculo; Fogini tiene inmunidad propia y Onésimo solo resistencia.','Casera · DM']
 ]),12)}${card('D · Conjuros y magia',audit([
 ['Cuatro conocidos y espacios 4/2','Progresión oficial de explorador 5. Los cuatro nombres están elegidos en hoja 02.','Marca, Curar heridas, Hablar con los animales, Pasar sin dejar rastro. Sin trucos. Recuperación en descanso largo.','Oficial'],
 ['Ataque +6 / CD 14','Sabiduría +3 y competencia +3: ataque 6; 8+3+3 = CD 14. Hoja 02 usa estas fórmulas.','Se mantienen +6 y 14. Hoja 01 imprime Destreza y resta Inteligencia en una fórmula incompatible; se conserva el original accesible.','Diferencia documentada'],
 ['Concentración de Marca / Pasar','Solo una concentración; Marca nivel 1/2 dura hasta una hora.','No suma Marca a Fogini, no convierte el +10 de Sigilo en invisibilidad y no aplica curación media como real.','Oficial'],
 ['Invocar Fogini','No se proporciona un conjuro, componentes o bloque completo de subclase.','Se modela como capacidad casera de acción adicional confirmada, sin inventar concentración o consumo de espacios.','Casera · DM']
 ]),12)}${card('E · Contenido de campaña',`<p>Deathsleep se nombra en los materiales. Onésimo y Fogini, sus frases, el vínculo y las ilustraciones son el contenido específico del personaje. Las imágenes y nombres de archivo «Fugini» corresponden a Fogini, nombre que aparece escrito en las hojas; se conserva esa grafía en la aplicación.</p><p>El usuario confirmó en esta conversación que invocarlo es una acción adicional y que se usan reglas comunitarias. También confirmó que no dispone de fuentes y que lo no especificado debe quedar pendiente. La autorización gráfica de la hoja 02 se conserva junto al aviso «Aprobación del DM requerida» de la ficha individual; esta última no se oculta.</p><p class="source-note">No se añaden capacidades de otra subclase Elementalista encontrada por similitud de nombre. Las decisiones futuras pueden registrarse en Bitácora como Decisión del DM sin reescribir automáticamente esta configuración.</p>`,12)}${card('F · Dudas y datos pendientes',`<details open><summary>Antes de empezar la sesión</summary><p>Registrar PG de Onésimo, temporales, dados, espacios restantes, cantidad de flechas, usos de Fogini, estado y PG del compañero, vínculo, efectos y condiciones. El botón de recursos completos requiere confirmación y deja flechas y estado del compañero por registrar.</p></details><details open><summary>Subclase comunitaria no identificada</summary><p>Pendientes: autor/texto, PG al aparecer o reinvocarse, cómo se recuperan o curan sus PG, detalles de aparición y alcance de la orden, funcionamiento exacto del vínculo cuando el compañero desaparece y secuencia de iniciativa. La ficha de Fogini aporta +2 de iniciativa, pero no establece sincronización automática.</p></details><details><summary>Elecciones y narrativa no documentadas</summary><p>Terreno y enemigo predilectos concretos, trasfondo, alineamiento, otros idiomas o competencias, cantidades de equipo, monedas, edad, familia, lugar de origen e historia personal. La app permite registrar hechos nuevos sin inventarlos.</p></details>`,12)}${card('Materiales y fuentes',`<div class="source-list"><p><b>Personaje:</b> cuatro PNG aportados: 01-OnesimoNvl-5, 02-OnesimoNvl-5, Fugini y OnesimoYFugini. <b>Referencia visual y funcional:</b> HTML de Eco aportado en BORRADORES. <b>Especificación:</b> prompt maestro de esta solicitud y aclaraciones del usuario.</p><p><b>Reglas verificadas:</b> <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/classes" target="_blank" rel="noopener">clases 2014 · explorador</a>, <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/races" target="_blank" rel="noopener">especies 2014 · elfo de los bosques</a>, <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/spells" target="_blank" rel="noopener">conjuros 2014</a>, <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/spellcasting" target="_blank" rel="noopener">lanzamiento y concentración</a>, <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/combat" target="_blank" rel="noopener">combate</a>, <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/adventuring" target="_blank" rel="noopener">descansos</a> y <a href="https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1.pdf" target="_blank" rel="noopener">SRD 5.1</a>. Estos enlaces de consulta requieren conexión; la app ya contiene sus resúmenes y funciona sin red.</p><p class="source-note">This work includes material taken from the System Reference Document 5.1 (“SRD 5.1”) by Wizards of the Coast LLC and available at https://dnd.wizards.com/resources/systems-reference-document. The SRD 5.1 is licensed under the Creative Commons Attribution 4.0 International License available at https://creativecommons.org/licenses/by/4.0/legalcode. Adaptaciones: resúmenes y traducción al español, interfaz y cálculos para Onésimo. Ilustraciones aportadas por el usuario; iconos SVG de equipo originales.</p></div>`,12)}${card('Documentos e ilustraciones originales',`<div class="reference-images">${[['onesimo-ficha.png','01 · Características y combate'],['onesimo-reglas.png','02 · Magia y reglas especiales'],['fogini-ficha.png','Fogini · ficha individual'],['onesimo-fogini.png','Onésimo y Fogini · ilustración']].map(x=>`<figure><a href="assets/imagen/${x[0]}" target="_blank" rel="noopener"><img src="assets/imagen/${x[0]}" alt="${x[1]}" loading="lazy"></a><figcaption>${x[1]} · pulsa para ampliar.</figcaption></figure>`).join('')}</div>`,12)}</div>`;
}
function renderAll(){renderFicha();renderLore();renderReglas();renderSimulador();renderMesa();renderBitacora();renderOficialidad();updateSummary();}
function refresh(){renderFicha();renderMesa();renderBitacora();updateSummary();updateSim();}
function updateSummary(){$('#live-resources').textContent='PG '+fmt(state.hp)+'/'+C.maxHP(state)+' · Espacios '+fmt(state.slots1)+'/4 | '+fmt(state.slots2)+'/2 · Flechas '+fmt(state.arrows)+' · Fogini '+fogStatus().toLowerCase();}
function go(tab,focus=false){if(!['ficha','lore','reglas','simulador','mesa','bitacora','oficialidad'].includes(tab))tab='ficha';currentTab=tab;$$('[role=tabpanel]').forEach(n=>{n.hidden=n.id!==tab;n.classList.toggle('active',n.id===tab);});$$('[role=tab]').forEach(n=>{const on=n.dataset.tab===tab;n.classList.toggle('active',on);n.setAttribute('aria-selected',String(on));n.tabIndex=on?0:-1;});if(focus)$('#tab-'+tab).focus();try{history.replaceState(null,'','#'+tab);}catch{}if(tab==='simulador')updateSim();}
function addLog(type,title,body,continuity=''){if(state.logs.length>=3000)return toast('Bitácora llena (3000 entradas): exporta y reorganiza.');state.logs.push({id:uid(),date:today(),session:'Turno '+state.round,type,title,body,continuity});}
function filename(label,ext){const clean=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,80);return 'Onesimo'+(state.campaign?'_'+clean(state.campaign):'')+'_'+label+'_'+today()+'.'+ext;}
function download(text,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportJSON(label='respaldo'){download(JSON.stringify(state,null,2),filename(label,'json'),'application/json');}
function readInt(id,min,max,nullable=false){const el=$(id),raw=el.value.trim();if(nullable&&!raw)return null;const n=Number(raw);if(!raw||!Number.isInteger(n)||n<min||n>max)throw new Error('Introduce un entero entre '+min+' y '+max+' en «'+el.closest('label').childNodes[0].textContent.trim()+'».');return n;}
function clearConcentrationIfNeeded(){if(C.conditions(state).some(c=>C.INCAP.includes(c))||state.deathFail>=3||state.exhaustion>=6){state.concentration='none';state.markTarget='';state.pendingConcentrationDC=null;}}
function shareText(){return `ONÉSIMO · Explorador 5 / Elementalista comunitario · ${state.campaign||'Campaña por registrar'} · D&D 2014\nCA 15 · Iniciativa +4 · Velocidad base 35 pies\nPG ${fmt(state.hp)}/${C.maxHP(state)} · Temporales ${fmt(state.temp)} · Dados ${fmt(state.hd)}/5d10\nEspacios: nivel 1 ${fmt(state.slots1)}/4; nivel 2 ${fmt(state.slots2)}/2 · Flechas ${fmt(state.arrows)}\nConcentración: ${concentrationName()}${state.concentration==='mark'?' sobre '+state.markTarget:''}${state.pendingConcentrationDC?' · Prueba pendiente CD '+state.pendingConcentrationDC:''}\nCondiciones: ${C.conditions(state).join(', ')||'ninguna registrada'} · Agotamiento ${state.exhaustion}\nFogini: ${fogStatus()} · PG ${fmt(state.fog.hp)}/19 · Invocaciones ${fmt(state.fog.uses)}/3 · Vínculo ${state.fog.bondActive?'activo':'no registrado activo'}\nPosición: ${state.position||'por registrar'}\nNotas: ${state.notes||'—'}`;}
async function applyDamage(){try{const n=readInt('#damage-amount',1,100000),type=$('#damage-type').value,target=$('#damage-target').value,critical=$('#damage-critical').checked;C.damage(state,n,type,critical,target);if(!await confirmChange('Aplicar daño real',`Receptor: ${target==='fog'?'Fogini':'Onésimo'}. Daño recibido ${n}${type==='fire'?' de fuego':''}. Se aplicarán las resistencias o inmunidad registradas y luego los PG temporales. Confirma que ya resolviste las demás modificaciones con el DM.`))return;const r=C.damage(state,n,type,critical,target);state=r.state;save();refresh();$('#damage-result').textContent=`Daño tras resistencia/inmunidad: ${r.damage}. Absorbido por temporales: ${r.absorbed}.${r.dc?' Resuelve CON +2 contra CD '+r.dc+'.':''}${target==='fog'&&state.fog.hp===0?' Fogini desapareció a 0 PG. El vínculo sigue como estaba registrado: confirma con el DM si continúa o finaliza y actualízalo manualmente.':''}${target==='onesimo'&&state.hp===0?' Onésimo queda inconsciente, concentración terminada.':''}`;toast(r.dc?'Daño registrado: queda una salvación de concentración pendiente.':'Daño registrado.');}catch(e){toast(e.message);}}
function heal(){try{if(state.hp===null)throw new Error('Registra los PG de Onésimo.');if(state.deathFail>=3||state.exhaustion>=6)throw new Error('La muerte registrada requiere resolución del DM.');const n=readInt('#heal-amount',1,100000);state.hp=Math.min(C.maxHP(state),state.hp+n);if(state.hp>0){state.deathSuccess=0;state.deathFail=0;}save();refresh();toast('Curación real registrada, hasta el máximo.');}catch(e){toast(e.message);}}
function resolveConcentration(){try{if(state.concentration==='none')throw new Error('No hay concentración activa.');const roll=readInt('#con-roll',1,20),dc=readInt('#con-dc',10,50000),total=roll+C.CFG.con,failed=total<dc;if(failed){state.concentration='none';state.markTarget='';}state.pendingConcentrationDC=null;save();refresh();toast('CON '+roll+' + 2 = '+total+' contra CD '+dc+': '+(failed?'concentración terminada.':'concentración mantenida.'));}catch(e){toast(e.message);}}
async function shortRest(){if(state.deathFail>=3||state.exhaustion>=6)return toast('La muerte registrada debe resolverse con el DM.');if(!await confirmChange('Terminar descanso corto','Confirma al menos una hora de descanso válido. No recupera espacios de explorador ni usos de Fogini. Puedes gastar dados de golpe disponibles después. Revisa la hora de duración del compañero y los conjuros con el DM.'))return;addLog('Otro','Descanso corto','Descanso válido confirmado; sin restauración automática de espacios, invocaciones o PG.');save();refresh();toast('Descanso corto registrado. Gasta dados si corresponde.');}
async function longRest(){try{const food=$('#rest-food').checked;C.longRest(state,food);if(!await confirmChange('Terminar descanso largo','Confirma un descanso largo válido según vuestra mesa, al menos 1 PG al inicio y ningún otro beneficio en 24 horas de ficción. Recupera PG, espacios 4/2, hasta 2 dados de golpe y 3 invocaciones. La duración de una hora termina la invocación durante el descanso; el vínculo se conserva como registro manual hasta que confirmes su final con el DM. No cura a Fogini. La reducción de agotamiento depende de la casilla de comida/bebida.'))return;state=C.longRest(state,food);addLog('Otro','Descanso largo','Descanso largo confirmado. PG, espacios 4/2, hasta dos dados y tres invocaciones recuperados; no se curó a Fogini.'+(food?' Comida y bebida suficientes para reducir un nivel de agotamiento.':''));save();refresh();toast('Descanso largo aplicado.');}catch(e){toast(e.message);}}
function spendHD(){try{if(state.hp===null||state.hd===null)throw new Error('Registra PG y dados disponibles.');if(state.hd<1)throw new Error('No quedan dados de golpe.');if(state.hp===0||state.deathFail>=3)throw new Error('Resuelve el estado a 0 PG con el DM antes de gastar dados.');const roll=readInt('#hd-roll',1,10);state.hd--;state.hp=Math.min(C.maxHP(state),state.hp+roll+C.CFG.con);save();refresh();toast('Un dado gastado: curación '+(roll+2)+' hasta tu máximo.');}catch(e){toast(e.message);}}
async function nextTurn(){if(!await confirmChange('Comenzar siguiente turno','Confirma que empieza el siguiente turno de Onésimo. Recuperarás acción, acción adicional, movimiento y reacción. No se recuperan espacios, flechas, invocaciones o PG.'))return;state.round++;state.turnApplied=false;state.reactionAvailable=true;save();refresh();toast('Nuevo turno disponible.');}
async function recordConcentration(){const selected=$('#concentration').value,target=$('#mark-target').value.trim();if(selected==='mark'&&!target)return toast('Escribe el objetivo de la marca.');if(state.concentration!=='none'&&selected!==state.concentration&&!await confirmChange('Cambiar concentración','Este registro sustituirá la concentración actual. No se consumen espacios porque registras un efecto ya lanzado.'))return;state.concentration=selected;state.markTarget=selected==='mark'?target:'';if(selected==='none')state.pendingConcentrationDC=null;clearConcentrationIfNeeded();save();refresh();toast('Concentración registrada.');}
async function endFog(){if(!await confirmChange('Finalizar invocación y vínculo','Confirma que la invocación o el vínculo finalizaron. Fogini quedará ausente; Onésimo dejará de recibir resistencia al fuego por este vínculo. No se devuelven usos ni se restauran los PG de Fogini.'))return;state.fog.status='absent';state.fog.remainingMinutes=0;state.fog.bondActive=false;save();refresh();toast('Invocación finalizada.');}
async function importBackup(file){if(!file)return;try{if(file.size>8*1024*1024)throw new Error('El archivo supera 8 MB.');const data=C.validate(JSON.parse(await file.text()));if(!await confirmChange('Restaurar respaldo de Onésimo',`Datos del ${new Date(data.updatedAt).toLocaleString('es-MX')}: ${data.logs.length} entradas, ${data.inventory.length} objetos. Se descargará una copia del estado actual antes de reemplazarlo. Solo se admite este personaje y versión.`))return;if(rawBad)download(rawBad,filename('original_intacto','json'),'application/json');else exportJSON('antes_de_importar');state=data;protectedSave=false;rawBad='';$('#storage-warning').hidden=true;save();renderAll();go(currentTab);toast('Respaldo validado e importado.');}catch(e){toast('Importación rechazada: '+e.message);}finally{if($('#import-file'))$('#import-file').value='';}}
async function reset(){if(!await confirmChange('Restablecer a Onésimo','Se descargará un respaldo y se restablecerán los recursos a pendientes, inventario inicial, notas y bitácora de Onésimo. No afecta a otros personajes.'))return;if(rawBad)download(rawBad,filename('original_intacto','json'),'application/json');else exportJSON('antes_de_restablecer');state=C.initial(D);protectedSave=false;rawBad='';$('#storage-warning').hidden=true;save();renderAll();go(currentTab);toast('Datos de Onésimo restablecidos.');}
document.addEventListener('submit',e=>{if(e.target.closest('#confirm-dialog'))return;e.preventDefault();try{
 if(e.target.id==='sim-form')return;
 if(e.target.id==='resource-form'){const max=readInt('#res-hpMax',1,1000),hp=readInt('#res-hp',0,max),temp=readInt('#res-temp',0,1000),hd=readInt('#res-hd',0,5),one=readInt('#res-slots1',0,4),two=readInt('#res-slots2',0,2),arrows=readInt('#res-arrows',0,99999,true),round=readInt('#res-round',1,999999);state.hpMax=max;state.hp=Math.min(hp,C.maxHP(state));state.temp=temp;state.hd=hd;state.slots1=one;state.slots2=two;state.arrows=arrows;state.round=round;state.reactionAvailable=$('#res-reaction').checked;if(hp>0){state.deathSuccess=0;state.deathFail=0;}clearConcentrationIfNeeded();save();refresh();toast('Estado de Onésimo registrado.');}
 if(e.target.id==='fog-form'){const status=$('#fog-status').value,hp=readInt('#fog-hp',0,19,true),uses=readInt('#fog-uses',0,3,true),minutes=readInt('#fog-minutes',0,60,true),bond=$('#fog-bond').checked;if(status==='active'&&(hp===null||hp===0||minutes===0))throw new Error('Fogini activo necesita PG por encima de 0 y duración no agotada.');Object.assign(state.fog,{status,hp,uses,remainingMinutes:minutes,bondActive:bond});save();refresh();toast('Estado ya resuelto de Fogini registrado; sin consumir usos.');}
 if(e.target.id==='item-form'){if(state.inventory.length>=500)throw new Error('Límite de 500 objetos.');const name=$('#item-name').value.trim();if(!name)throw new Error('Escribe el nombre del objeto.');state.inventory.push({id:uid(),name,qty:readInt('#item-qty',0,99999),notes:$('#item-notes').value,kind:$('#item-kind').value,icon:$('#item-icon').value});save();refresh();toast('Objeto registrado.');}
 if(e.target.id==='log-form'){if(state.logs.length>=3000)throw new Error('Límite de 3000 entradas.');const title=$('#log-title').value.trim(),body=$('#log-body').value.trim();if(!title||!body)throw new Error('El registro necesita título y contenido.');state.logs.push({id:uid(),date:$('#log-date').value,session:$('#log-session').value,type:$('#log-type').value,title,body,continuity:$('#log-continuity').value});state.logDraft={date:'',session:'',type:'Exploración',title:'',body:'',continuity:''};save();renderBitacora();toast('Entrada guardada.');}
 }catch(err){toast(err.message);}});
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab)return go(tab.dataset.tab);const link=e.target.closest('[data-go]');if(link){go(link.dataset.go);$('#tab-'+link.dataset.go).scrollIntoView({block:'nearest',inline:'center'});return;}const preset=e.target.closest('[data-preset]');if(preset)return applyPreset(preset.dataset.preset);const item=e.target.closest('[data-delete-item]');if(item){if(await confirmChange('Quitar objeto','Se eliminará este objeto del inventario de Onésimo.')){state.inventory=state.inventory.filter(x=>x.id!==item.dataset.deleteItem);save();refresh();}return;}const log=e.target.closest('[data-delete-log]');if(log){if(await confirmChange('Eliminar entrada','Se eliminará esta entrada de la bitácora local. Puedes exportar un respaldo antes.')){state.logs=state.logs.filter(x=>x.id!==log.dataset.deleteLog);save();renderBitacora();}return;}
 const actions={'apply-turn':applyTurn,'apply-damage':applyDamage,'apply-heal':heal,'resolve-concentration':resolveConcentration,'short-rest':shortRest,'long-rest':longRest,'spend-hd':spendHD,'next-turn':nextTurn,'record-concentration':recordConcentration,'end-fog':endFog,'export-json':()=>exportJSON(),'export-text':()=>download(`BITÁCORA DE ONÉSIMO · ${state.campaign||'Campaña pendiente'}\n\n`+state.logs.map(l=>`${l.date} | ${l.session} | ${l.type}\n${l.title}\n${l.body}\nContinuidad: ${l.continuity||'—'}\n`).join('\n---\n\n'),filename('bitacora','txt')),'reset-state':reset,'export-original':()=>download(rawBad,filename('original_intacto','json'),'application/json'),'copy-state':async()=>{try{await navigator.clipboard.writeText(shareText());toast('Estado copiado.');}catch{const n=$('#copy-fallback');n.hidden=false;n.value=shareText();n.focus();n.select();toast('Copia el texto seleccionado con Ctrl+C.');}},'expand-rules':()=>{$$('#reglas details:not([hidden])').forEach(d=>d.open=true);},'full-resources':async()=>{if(!await confirmChange('Confirmar recursos completos','Confirma que Onésimo tiene su máximo de PG, 0 temporales, cinco dados d10 y espacios 4/2, y que quedan tres usos de Fogini. No se cambia el estado o PG de Fogini ni se inventa la cantidad de flechas. Los efectos y condiciones se conservan para revisión.'))return;state.hp=C.maxHP(state);state.temp=0;state.hd=5;state.slots1=4;state.slots2=2;state.fog.uses=3;state.deathSuccess=0;state.deathFail=0;save();refresh();toast('Recursos completos confirmados. Registra flechas y estado de Fogini.');},'record-death':()=>{try{if(state.hp!==0)throw new Error('Las salvaciones de muerte se registran a 0 PG.');state.deathSuccess=readInt('#death-success',0,3);state.deathFail=readInt('#death-fail',0,3);clearConcentrationIfNeeded();save();refresh();toast('Salvaciones registradas.');}catch(err){toast(err.message);}},'death-20':async()=>{if(state.hp!==0||state.deathFail>=3||state.exhaustion>=6)return toast('Necesita 0 PG y no haber muerto.');if(await confirmChange('20 natural en salvación de muerte','Confirma el 20 natural: recuperas 1 PG y reinicias éxitos y fallos.')){state.hp=1;state.deathSuccess=0;state.deathFail=0;save();refresh();}}};const fn=actions[e.target.closest('button')?.id];if(fn)await fn();});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.bind){state[t.dataset.bind]=t.value;save();if(t.dataset.bind==='campaign')renderLore();}if(t.dataset.fogBind){state.fog[t.dataset.fogBind]=t.value;save();}if(t.dataset.logDraft||t.id==='log-type'){if(!state.logDraft)state.logDraft={date:'',session:'',type:'Exploración',title:'',body:'',continuity:''};state.logDraft[t.dataset.logDraft||'type']=t.value;save();}if(t.closest('#sim-form'))updateSim();if(t.id==='rules-search'){const q=t.value.toLowerCase();let count=0;$$('#reglas [data-search]').forEach(d=>{d.hidden=!d.dataset.search.includes(q);if(!d.hidden)count++;});$('#rules-empty').hidden=count>0;}if(t.id==='log-search')$('#log-history').innerHTML=renderLogs(t.value);if(t.dataset.itemField){const item=state.inventory.find(x=>x.id===t.closest('[data-item]').dataset.item);if(t.dataset.itemField==='qty'){const n=Number(t.value);if(!t.value.trim()||!Number.isInteger(n)||n<0||n>99999){t.setCustomValidity('Cantidad entera de 0 a 99999.');return;}t.setCustomValidity('');item.qty=n;}else item[t.dataset.itemField]=t.value;save();renderFicha();updateSim();}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='import-file')importBackup(t.files[0]);if(t.dataset.condition){state.conditions=t.checked?[...state.conditions,t.dataset.condition]:state.conditions.filter(v=>v!==t.dataset.condition);clearConcentrationIfNeeded();save();refresh();}if(t.dataset.fogCondition){state.fog.conditions=t.checked?[...state.fog.conditions,t.dataset.fogCondition]:state.fog.conditions.filter(v=>v!==t.dataset.fogCondition);save();refresh();}if(t.id==='exhaustion'){state.exhaustion=Number(t.value);if(state.hp!==null)state.hp=Math.min(state.hp,C.maxHP(state));clearConcentrationIfNeeded();save();refresh();}});
$('.tabs').addEventListener('keydown',e=>{const tabs=$$('[role=tab]'),index=tabs.indexOf(document.activeElement);if(index<0||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;go(tabs[n].dataset.tab,true);tabs[n].scrollIntoView({block:'nearest',inline:'center'});});
window.addEventListener('hashchange',()=>go(location.hash.slice(1)));window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue!==JSON.stringify(state)){protectedSave=true;warnStorage('Otra ventana modificó esta hoja. El guardado se ha detenido para evitar sobrescribirla. Exporta esta copia y recarga para abrir la versión guardada.');$('#save-status').textContent='Conflicto entre ventanas · escritura detenida';}});
function applyPreset(name){const values={mark:{action:'bow',bonus:'mark',distance:60,move:0,slotLevel:1,markLevel:1},pair:{action:'bow',bonus:'command',distance:60,move:0,slotLevel:1},summon:{action:'bow',bonus:'summon',distance:60,move:0,slotLevel:1},stealth:{action:'pass',bonus:'none',distance:0,move:0,slotLevel:2},heal:{action:'cure',bonus:'command',distance:0,move:0,slotLevel:1}}[name];for(const[k,v]of Object.entries(values))$('#sim-'+k).value=v;$('#sim-attackCount').value=2;$('#sim-direction').value='toward';$('#sim-reaction').value='none';$('#sim-hostileNear').checked=false;$('#sim-reactionTrigger').checked=false;if(name==='pair')$('#sim-markOnTarget').checked=state.concentration==='mark';if(name==='mark')$('#sim-target').value=state.markTarget;updateSim();toast('Preset cargado. Confirma objetivo, componentes y situación de Fogini antes de aplicar.');}
renderAll();go(location.hash.slice(1)||'ficha');$('#save-status').textContent=protectedSave?'Guardado protegido · revisar Bitácora':storageOkay?'Local · guardado automático':'Sin guardado · exporta un JSON';
})();
